sp_widget.client_script:
api.controller = function($scope) {
    var c = this;

    c.reservationNumber = "";
    c.guestEmail = "";
    c.message = "";
    c.messageType = "";
    c.loading = false;

    c.submitLookup = function() {
        c.message = "";
        c.messageType = "";

        if (!c.reservationNumber || !c.reservationNumber.trim()) {
            c.message = "Please enter your reservation number.";
            c.messageType = "error";
            return;
        }

        if (!c.guestEmail || !c.guestEmail.trim()) {
            c.message = "Please enter the email address used for your reservation.";
            c.messageType = "error";
            return;
        }

        var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

        if (!emailPattern.test(c.guestEmail.trim())) {
            c.message = "Please enter a valid email address.";
            c.messageType = "error";
            return;
        }

        c.message = "The reservation lookup service is not connected yet. Please try again once the booking service is ready.";
        c.messageType = "info";
    };
}

sp_widget.css:
.guest-lookup-page {
  min-height: 650px;
  padding: 65px 20px 55px;
  background: #faf6ef;
  font-family: Arial, sans-serif;
}

.lookup-heading {
  text-align: center;
  max-width: 650px;
  margin: 0 auto 35px;
}

.lookup-eyebrow {
  display: inline-block;
  color: #9a805d;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 3px;
  margin-bottom: 12px;
}

.lookup-heading h1 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 38px;
  font-weight: 500;
  margin: 0 0 12px;
}

.lookup-heading p {
  color: #6f756f;
  font-size: 15px;
  line-height: 1.7;
  margin: 0;
}

.lookup-card {
  max-width: 510px;
  margin: 0 auto;
  padding: 38px 42px;
  background: #ffffff;
  border: 1px solid #e7e1d4;
  border-radius: 10px;
  box-shadow: 0 12px 35px rgba(31, 58, 48, 0.07);
}

.lookup-icon {
  width: 55px;
  height: 55px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 18px;
  background: #e8eee9;
  border-radius: 50%;
  color: #1f3a30;
  font-size: 23px;
}

.lookup-card h2 {
  color: #1f3a30;
  font-family: Georgia, serif;
  font-size: 25px;
  font-weight: 500;
  text-align: center;
  margin: 0 0 8px;
}

.lookup-description {
  color: #6f756f;
  font-size: 13px;
  text-align: center;
  line-height: 1.6;
  margin: 0 0 28px;
}

.lookup-card .form-group {
  margin-bottom: 20px;
}

.lookup-card label {
  display: block;
  color: #2a2d29;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 8px;
}

.lookup-card input {
  width: 100%;
  height: 46px;
  padding: 0 14px;
  border: 1px solid #e7e1d4;
  border-radius: 5px;
  background: #faf6ef;
  color: #2a2d29;
  font-size: 14px;
  box-sizing: border-box;
  outline: none;
}

.lookup-card input:focus {
  border-color: #1f3a30;
  box-shadow: 0 0 0 2px rgba(31, 58, 48, 0.08);
}

.lookup-card input::placeholder {
  color: #a3a69f;
}

.lookup-button {
  width: 100%;
  height: 48px;
  margin-top: 5px;
  border: none;
  border-radius: 5px;
  background: #1f3a30;
  color: #ffffff;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.5px;
  cursor: pointer;
  transition: background 0.2s ease;
}

.lookup-button:hover {
  background: #162a22;
}

.lookup-button:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.lookup-button i {
  margin-right: 8px;
}

.lookup-message {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 13px 15px;
  margin-top: 20px;
  border-radius: 5px;
  font-size: 13px;
  line-height: 1.6;
}

.lookup-message.error {
  background: #f9e9e6;
  color: #9c3d31;
}

.lookup-message.info {
  background: #e8eee9;
  color: #1f3a30;
}

.lookup-help {
  display: flex;
  align-items: flex-start;
  gap: 9px;
  padding-top: 20px;
  margin-top: 25px;
  border-top: 1px solid #e7e1d4;
  color: #8a8e87;
  font-size: 11px;
  line-height: 1.6;
}

.lookup-help i {
  color: #9a805d;
  margin-top: 2px;
}

.lookup-back {
  text-align: center;
  margin-top: 28px;
}

.lookup-back a {
  color: #1f3a30;
  font-size: 13px;
  text-decoration: none;
}

.lookup-back a:hover {
  color: #9a805d;
}

.lookup-back i {
  margin-right: 6px;
}

@media (max-width: 600px) {
  .guest-lookup-page {
    padding: 40px 15px;
  }

  .lookup-heading h1 {
    font-size: 30px;
  }

  .lookup-card {
    padding: 30px 22px;
  }
}
